static float floatFromU16Pair(quint16 lo, quint16 hi)
{
    const quint32 u = quint32(lo) | (quint32(hi) << 16);
    float f = 0.f;
    std::memcpy(&f, &u, sizeof(f));
    return f;
}

column6:
static void floatToU16Pair(float f, quint16 *lo, quint16 *hi)
{
    quint32 u = 0;
    static_assert(sizeof(float) == sizeof(quint32), "float size");
    std::memcpy(&u, &f, sizeof(u));
    *lo = quint16(u & 0xFFFFu);
    *hi = quint16((u >> 16) & 0xFFFFu);
}
